SELECT CASE WHEN s.city IN ('Bangkok', 'Singapore') THEN 'priority' ELSE 'other' END AS city_group, DATE_FORMAT(s.opened_date, 'yyyy-MM') AS opened_month, COUNT(i.quantity) AS quantity_count, SUM(i.quantity) AS total_quantity FROM inventory i LEFT JOIN stores s ON i.store_id = s.id INNER JOIN products p ON i.product_id = p.id WHERE p.launch_date < '2024-04-01' GROUP BY CASE WHEN s.city IN ('Bangkok', 'Singapore') THEN 'priority' ELSE 'other' END, DATE_FORMAT(s.opened_date, 'yyyy-MM') ORDER BY opened_month DESC, city_group LIMIT 3
